fun tasksText(n: Int): String {
    val word = when {
        n % 100 in 11..14 -> "задач"
        n % 10 == 1 -> "задача"
        n % 10 in 2..4 -> "задачи"
        else -> "задач"
    }
    return "У вас $n $word"
}

